import{_ as i,a0 as l,w as r,s as d,ao as a,I as t,x as o,a1 as p,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"什么是 Linux “oops”？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是 Linux “oops”？ | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是 Linux “oops”？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是 Linux “oops”？ | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180215 What is a Linux -oops","title":"什么是 Linux “oops”？","tag":"201804","desc":""},"relativePath":"201804/20180215 What is a Linux -oops.md","filePath":"[post].md"}'),u={name:"201804/20180215 What is a Linux -oops.md"};function g(k,s,b,m,f,h){const e=l("Link");return r(),d("div",null,[s[21]||(s[21]=a(`<h1 id="什么是-linux-oops" tabindex="-1">什么是 Linux “oops”？ <a class="header-anchor" href="#什么是-linux-oops" aria-label="Permalink to “什么是 Linux “oops”？”">​</a></h1><blockquote><p>Linux 内核正在盯着你，当它检测到系统上运行的某些东西违反了正常内核行为时，它会关闭系统并发出一个“oops”！</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/02/broken-wine-glass-100749404-large.jpg" alt=""></p><p>如果你检查你的 Linux 系统上运行的进程，你可能会对一个叫做 “kerneloops” 的进程感到好奇。提示一下，它是 “kernel oops”，而不是 “kerne loops”。</p><p>坦率地说，“oops” 是 Linux 内核的一部分出现了偏差行为。你有做错了什么吗？可能没有。但有一些不对劲。而那个做了错事的进程可能已经被 CPU 结束。最糟糕的是，内核可能会报错并突然关闭系统。</p><p>请注意，“oops” 不是首字母缩略词。它不代表像“<ruby>面向对象的编程和系统<rt>object-oriented programming and systems</rt></ruby>” 或“<ruby>超出程序规范<rt>out of procedural specs</rt></ruby>” 之类的东西。它实际上就是“哎呀” （oops），就像你刚掉下一杯酒或踩在你的猫身上。哎呀！ “oops” 的复数是 “oopses”。</p><p>oops 意味着系统上运行的某些东西违反了内核有关正确行为的规则。也许代码尝试采取不允许的代码路径或使用无效指针。不管它是什么，内核 —— 总是在监测进程的错误行为 —— 很可能会阻止特定进程，并将它做了什么的消息写入控制台、 <code>/var/log/dmesg</code> 或 <code>/var/log/kern.log</code> 中。</p><p>oops 可能是由内核本身引起的，也可能是某些进程试图让内核违反在系统上能做的事以及它们被允许做的事。</p><p>oops 将生成一个<ruby>崩溃签名<rt>crash signature</rt></ruby>，这可以帮助内核开发人员找出错误并提高代码质量。</p><p>系统上运行的 kerneloops 进程可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kernoops 881 1 0 Feb11 ? 00:00:01 /usr/sbin/kerneloops</span></span></code></pre></div><p>你可能会注意到该进程不是由 root 运行的，而是由名为 “kernoops” 的用户运行的，并且它的运行时间极少。实际上，分配给这个特定用户的唯一任务是运行 kerneloops。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo grep kernoops /etc/passwd</span></span>
<span class="line"><span>kernoops:x:113:65534:Kernel Oops Tracking Daemon,,,:/:/bin/false</span></span></code></pre></div>`,13)),t("p",null,[s[1]||(s[1]=o("如果你的 Linux 系统不带有 kerneloops（比如 Debian），你可以考虑添加它。查看这个 ",-1)),p(e,{href:"https://packages.debian.org/stretch/kerneloops"},{default:n(()=>[...s[0]||(s[0]=[o("Debian 页面",-1)])]),_:1}),s[2]||(s[2]=o("了解更多信息。",-1))]),s[22]||(s[22]=a('<h3 id="什么时候应该关注-oops" tabindex="-1">什么时候应该关注 oops？ <a class="header-anchor" href="#什么时候应该关注-oops" aria-label="Permalink to “什么时候应该关注 oops？”">​</a></h3><p>一般 oops 没什么大不了的。它在一定程度上取决于特定进程所扮演的角色。它也取决于 oops 的类别。</p><p>有些 oops 很严重，会导致<ruby>系统恐慌<rt>system panic</rt></ruby>。从技术上讲，系统恐慌是 oops 的一个子集（即更严重的 oops）。当内核检测到的问题足够严重以至于内核认为它（内核）必须立即停止运行以防止数据丢失或对系统造成其他损害时会出现。因此，系统需要暂停并重新启动，以防止任何不一致导致不可用或不可靠。所以系统恐慌实际上是为了保护自己免受不可挽回的损害。</p><p>总之，所有的内核恐慌都是 oops，但并不是所有的 oops 都是内核恐慌。</p><p><code>/var/log/kern.log</code> 和相关的轮转日志（<code>/var/log/kern.log.1</code>、<code>/var/log/kern.log.2</code> 等）包含由内核生成并由 syslog 处理的日志。</p>',5)),t("p",null,[s[4]||(s[4]=o("kerneloops 程序收集并默认将错误信息提交到 ",-1)),p(e,{href:"http://oops.kernel.org/"},{default:n(()=>[...s[3]||(s[3]=[o("http://oops.kernel.org/",-1)])]),_:1}),s[5]||(s[5]=o("，在那里它会被分析并呈现给内核开发者。此进程的配置详细信息在 ",-1)),s[6]||(s[6]=t("code",null,"/etc/kerneloops.conf",-1)),s[7]||(s[7]=o(" 文件中指定。你可以使用下面的命令轻松查看设置：",-1))]),s[23]||(s[23]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /etc/kerneloops.conf | grep -v ^# | grep -v ^$</span></span>
<span class="line"><span>[sudo] password for shs:</span></span>
<span class="line"><span>allow-submit = ask</span></span>
<span class="line"><span>allow-pass-on = yes</span></span>
<span class="line"><span>submit-url = http://oops.kernel.org/submitoops.php</span></span>
<span class="line"><span>log-file = /var/log/kern.log</span></span>
<span class="line"><span>submit-pipe = /usr/share/apport/kernel_oops</span></span></code></pre></div><p>在上面的（默认）设置中，内核问题可以被提交，但要求用户获得许可。如果设置为 <code>allow-submit = always</code>，则不会询问用户。</p><p>调试内核问题是使用 Linux 系统的更高级技巧之一。幸运的是，大多数 Linux 用户很少或从没有经历过 oops 或内核恐慌。不过，知道 kerneloops 这样的进程在系统中执行什么操作，了解可能会报告什么以及系统何时遇到严重的内核冲突也是很好的。</p><hr>`,4)),t("p",null,[s[9]||(s[9]=o("via: ",-1)),p(e,{href:"https://www.networkworld.com/article/3254778/linux/what-is-a-linux-oops.html"},{default:n(()=>[...s[8]||(s[8]=[o("https://www.networkworld.com/article/3254778/linux/what-is-a-linux-oops.html",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=o("作者：",-1)),p(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[10]||(s[10]=[o("Sandra Henry-Stocker",-1)])]),_:1}),s[14]||(s[14]=o(" 译者：",-1)),p(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[11]||(s[11]=[o("geekpi",-1)])]),_:1}),s[15]||(s[15]=o(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[o("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[o("LCTT",-1)])]),_:1}),s[19]||(s[19]=o(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[o("Linux中国",-1)])]),_:1}),s[20]||(s[20]=o(" 荣誉推出",-1))])])}const C=i(u,[["render",g]]);export{w as __pageData,C as default};
